import{_ as d,o,c as r,O as e}from"./chunks/framework.db831a78.js";const c=JSON.parse('{"title":"Monorepo 概述与方案对比","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/Monorepo/Monorepo-概述与方案对比.md","filePath":"frontend/Monorepo/Monorepo-概述与方案对比.md","lastUpdated":null}'),n={name:"frontend/Monorepo/Monorepo-概述与方案对比.md"};function a(s,t,h,p,l,i){return o(),r("div",null,t[0]||(t[0]=[e('<h1 id="monorepo-概述与方案对比" tabindex="-1">Monorepo 概述与方案对比 <a class="header-anchor" href="#monorepo-概述与方案对比" aria-label="Permalink to &quot;Monorepo 概述与方案对比&quot;">​</a></h1><h2 id="什么是-monorepo" tabindex="-1">什么是 Monorepo <a class="header-anchor" href="#什么是-monorepo" aria-label="Permalink to &quot;什么是 Monorepo&quot;">​</a></h2><p><strong>Monorepo</strong>（单一仓库）是将多个项目/包放在同一个仓库中管理的开发模式。与之相对的是 <strong>MultiRepo</strong>（多仓库）。</p><h3 id="优势-vs-劣势" tabindex="-1">优势 vs 劣势 <a class="header-anchor" href="#优势-vs-劣势" aria-label="Permalink to &quot;优势 vs 劣势&quot;">​</a></h3><table><thead><tr><th></th><th>Monorepo</th><th>MultiRepo</th></tr></thead><tbody><tr><td><strong>代码复用</strong></td><td>✅ 跨项目共享代码零成本</td><td>❌ 需发布 npm 包</td></tr><tr><td><strong>统一构建</strong></td><td>✅ 一条命令构建所有包</td><td>❌ 各自配置 CI/CD</td></tr><tr><td><strong>原子提交</strong></td><td>✅ 跨包修改一个 PR 搞定</td><td>❌ 需多个仓库协同</td></tr><tr><td><strong>依赖管理</strong></td><td>✅ 公共依赖提升，节省磁盘</td><td>❌ 重复安装</td></tr><tr><td><strong>权限控制</strong></td><td>❌ 所有代码可见</td><td>✅ 可精确控制</td></tr><tr><td><strong>构建速度</strong></td><td>❌ 仓库膨胀后变慢（可缓存解决）</td><td>✅ 独立构建</td></tr><tr><td><strong>学习成本</strong></td><td>❌ 工具链配置较复杂</td><td>✅ 简单直接</td></tr></tbody></table><h3 id="主流方案对比" tabindex="-1">主流方案对比 <a class="header-anchor" href="#主流方案对比" aria-label="Permalink to &quot;主流方案对比&quot;">​</a></h3><table><thead><tr><th>方案</th><th>包管理</th><th>构建缓存</th><th>任务编排</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>pnpm workspace</strong></td><td>pnpm</td><td>无</td><td>无</td><td>小型 Monorepo</td></tr><tr><td><strong>Turborepo</strong></td><td>任意</td><td>✅ 云端缓存</td><td>✅ 并行管道</td><td>中大型项目</td></tr><tr><td><strong>Nx</strong></td><td>任意</td><td>✅ 本地+云端</td><td>✅ 依赖图</td><td>大型企业项目</td></tr><tr><td><strong>Rush</strong></td><td>内置</td><td>✅</td><td>✅</td><td>微软生态</td></tr><tr><td><strong>Lerna</strong></td><td>npm/pnpm</td><td>无</td><td>✅ 批量命令</td><td>传统 Monorepo</td></tr></tbody></table><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h2><table><thead><tr><th>场景</th><th>推荐方案</th></tr></thead><tbody><tr><td>小型团队，简单项目</td><td>pnpm workspace 足够</td></tr><tr><td>需要构建缓存加速</td><td>Turborepo</td></tr><tr><td>大型企业，多技术栈</td><td>Nx</td></tr><tr><td>已有 Lerna 项目</td><td>Lerna + pnpm</td></tr></tbody></table>',9)]))}const m=d(n,[["render",a]]);export{c as __pageData,m as default};
